<?php
require_once __DIR__.'/includes/auth.php';require_auth();$id=(int)($_GET['id']??0);$asset=get_asset($id);if(!$asset||!asset_can_manage($asset)){http_response_code(403);exit('Access denied.');}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim((string)($_POST['title']??''));$visibility=(string)($_POST['visibility']??'organization');$status=(string)($_POST['status']??'active');if($title==='')$error='Title is required.';elseif(!in_array($visibility,['private','organization','public'],true)||!in_array($status,['active','archived'],true))$error='Invalid selection.';else{try{$category=(int)($_POST['category_id']??0)?:null;db()->prepare('UPDATE assets SET title=?,description=?,category_id=?,visibility=?,status=? WHERE id=?')->execute([mb_substr($title,0,190),trim((string)($_POST['description']??'')),$category,$visibility,$status,$id]);sync_asset_tags($id,(string)($_POST['tags']??''));audit('asset_edited','Updated asset “'.$title.'”.');flash('success','Asset information updated.');redirect('asset-details.php?id='.$id);}catch(PDOException){$error='Could not save the asset. Check the selected category.';}}}
$asset=get_asset($id);$categories=db()->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();$tagString=implode(', ',array_column(tags_for_asset($id),'name'));$pageTitle='Edit asset';$pageSubtitle=$asset['asset_code'];require __DIR__.'/includes/header.php';?>
<div class="row"><div class="col-xl-8"><div class="card"><div class="card-body p-4"><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="mb-3"><label class="form-label">Title</label><input class="form-control" name="title" maxlength="190" required value="<?=e($asset['title'])?>"></div><div class="mb-3"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="5"><?=e($asset['description'])?></textarea></div><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Category</label><select class="form-select" name="category_id"><option value="">Uncategorized</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$asset['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-6 mb-3"><label class="form-label">Tags</label><input class="form-control" name="tags" value="<?=e($tagString)?>"></div><div class="col-md-6 mb-3"><label class="form-label">Visibility</label><select class="form-select" name="visibility"><?php foreach(['private','organization','public'] as $value):?><option <?=$asset['visibility']===$value?'selected':''?> value="<?=$value?>"><?=ucfirst($value)?></option><?php endforeach;?></select></div><div class="col-md-6 mb-4"><label class="form-label">Status</label><select class="form-select" name="status"><option value="active" <?=$asset['status']==='active'?'selected':''?>>Active</option><option value="archived" <?=$asset['status']==='archived'?'selected':''?>>Archived</option></select></div></div><button class="btn btn-primary">Save changes</button><a class="btn btn-light" href="<?=e(url('asset-details.php?id='.$id))?>">Cancel</a></form></div></div></div></div>
